    use super::*;

    #[test]
    fn test_eval_and_optimize() {
        let mut store = HashMap::new();
        store.insert("x".to_string(), 5);

        // (x + 0)  --> optimize to x
        let expr = Exp::Plus(Box::new(Exp::Var("x".into())), Box::new(Exp::Const(0)));
        assert_eq!(expr.eval(&store), 5);
        let opt = expr.clone().optimize();
        assert_eq!(opt, Exp::Var("x".into()));
        assert_eq!(opt.eval(&store), 5);

        // (0 * y) --> optimize to 0
        let expr2 = Exp::Mult(Box::new(Exp::Const(0)), Box::new(Exp::Var("y".into())));
        assert_eq!(expr2.eval(&store), 0);
        let opt2 = expr2.clone().optimize();
        assert_eq!(opt2, Exp::Const(0));
        assert_eq!(opt2.eval(&store), 0);

        // (2 * 3) --> optimize to 6
        let expr3 = Exp::Mult(Box::new(Exp::Const(2)), Box::new(Exp::Const(3)));
        assert_eq!(expr3.eval(&store), 6);
        let opt3 = expr3.clone().optimize();
        assert_eq!(opt3, Exp::Const(6));
        assert_eq!(opt3.eval(&store), 6);

        // (1 * (x+1)) --> optimize to x+1
        let sub = Exp::Plus(Box::new(Exp::Var("x".into())), Box::new(Exp::Const(1)));
        let expr4 = Exp::Mult(Box::new(Exp::Const(1)), Box::new(sub.clone()));
        assert_eq!(expr4.eval(&store), 6);
        let opt4 = expr4.clone().optimize();
        assert_eq!(opt4, sub);
        assert_eq!(opt4.eval(&store), 6);
    }
